<?php
declare(strict_types=1);
require_once __DIR__ . '/../bootstrap/app.php';require_role('ADMIN');
$stats=['members'=>(int)(db_one('SELECT COUNT(*) n FROM MEMBER')['n']??0),'active'=>(int)(db_one("SELECT COUNT(*) n FROM MEMBERSHIP WHERE Status='ACTIVE' AND EndsOn>=CURDATE()")['n']??0),'trainers'=>(int)(db_one("SELECT COUNT(*) n FROM TRAINER WHERE Status='ACTIVE'")['n']??0),'trainer_requests'=>(int)(db_one("SELECT COUNT(*) n FROM TRAINER t JOIN USER_ACCOUNT u ON u.UserAccountID=t.UserAccountID WHERE t.Status='PENDING' AND u.Status='PENDING'")['n']??0),'revenue'=>(float)(db_one("SELECT COALESCE(SUM(Amount),0) n FROM MEMBERSHIP_PAYMENT WHERE Status='PAID'")['n']??0),'inside'=>(int)(db_one('SELECT COUNT(*) n FROM GYM_VISIT WHERE CheckedOutAt IS NULL')['n']??0)];
$upcoming=db_all("SELECT gc.Name,gc.StartsAt,gc.Capacity,CONCAT(t.FirstName,' ',t.LastName) TrainerName FROM GYM_CLASS gc LEFT JOIN TRAINER t ON t.TrainerID=gc.TrainerID WHERE gc.Status='SCHEDULED' AND gc.StartsAt>=NOW() ORDER BY gc.StartsAt LIMIT 5");$pageTitle='Admin dashboard';$pageSubtitle='Gym operations at a glance';include V3_ROOT.'/includes/header.php';?>
<section class="stats-grid"><article class="stat-card"><span>Members</span><strong><?=$stats['members']?></strong><small><?=$stats['active']?> active memberships</small></article><article class="stat-card"><span>Active trainers</span><strong><?=$stats['trainers']?></strong></article><article class="stat-card"><span>Trainer requests</span><strong><?=$stats['trainer_requests']?></strong><small><a href="<?=e(base_url('admin/trainers.php?status=PENDING'))?>">Review requests</a></small></article><article class="stat-card"><span>Paid revenue</span><strong><?=e(number_format($stats['revenue'],2))?></strong></article><article class="stat-card"><span>Inside gym</span><strong><?=$stats['inside']?></strong></article></section><section class="panel"><h2>Upcoming classes</h2><div class="table-wrap"><table><caption class="sr-only">Upcoming classes</caption><thead><tr><th>Class</th><th>Trainer</th><th>Starts</th><th>Capacity</th></tr></thead><tbody><?php foreach($upcoming as $row):?><tr><td><?=e($row['Name'])?></td><td><?=e($row['TrainerName']??'TBA')?></td><td><?=e($row['StartsAt'])?></td><td><?=(int)$row['Capacity']?></td></tr><?php endforeach;?><?php if(!$upcoming):?><tr><td colspan="4">No upcoming classes.</td></tr><?php endif;?></tbody></table></div></section><?php include V3_ROOT.'/includes/footer.php';?>
